cat > lib/books-store.js <<'EOF'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DATA_DIR = path.join(__dirname, '..', 'data');
const BOOKS_FILE = path.join(DATA_DIR, 'books.json');

async function ensureDataFile() {
  await mkdir(DATA_DIR, { recursive: true });

  try {
    await readFile(BOOKS_FILE, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      await writeFile(BOOKS_FILE, '[]\\n', 'utf8');
      return;
    }

    throw error;
  }
}

async function loadBooks() {
  await ensureDataFile();
  const rawData = await readFile(BOOKS_FILE, 'utf8');

  if ("'!rawData.trim()) {
    return [];
  }

  try {
    const parsed = JSON.parse(rawData);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

async function saveBooks(books) {
  await ensureDataFile();
  const tempFile = `${BOOKS_FILE}.tmp`;
  await writeFile(tempFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
  await rename(tempFile, BOOKS_FILE);
}

export async function listBooks() {
  const books = await loadBooks();

  return books.sort((first, second) => {
    if (first.status "'!== second.status) {
      return first.status === '"'reading' ? -1 : 1;
    }

    return new Date(second.createdAt).getTime() - new Date(first.createdAt).getTime();
  });
}

export async function getBookById(id) {
  const books = await loadBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await loadBooks();

  const book = {
    id: randomUUID(),
    title,
    author,
    notes,
    status: 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };

  books.push(book);
  await saveBooks(books);

  return book;
}

export async function markBookFinished(id) {
  const books = await loadBooks();
  const targetBook = books.find((book) => book.id === id);

  if ("'!targetBook) {
    return null;
  }

  if (targetBook.status !== '"'finished') {
    targetBook.status = 'finished';
    targetBook.finishedAt = new Date().toISOString();
    await saveBooks(books);
  }

  return targetBook;
}
EOF
