import express from 'express';
import {
  addBook,
  getBookById,
  listBooks,
  markBookFinished,
} from './lib/books-store.js';

const app = express();
const port = Number(process.env.PORT) || 3000;

app.use(express.urlencoded({ extended: false }));
app.use(express.static('public'));

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('\"', '&quot;')
    .replaceAll(\"'\", '&#39;');
}

function renderLayout({ title, content }) {
  return "'`<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(title)}</title>
    <link rel="stylesheet" href="/styles.css" />
  </head>
  <body>
    <main class="container">
      ${content}
    </main>
  </body>
</html>`;
}

function renderBookItem(book) {
  const detailPath = `/books/${encodeURIComponent(book.id)}`;

  return `<li class="book-row">
    <div>
      <a class="book-link" href="${detailPath}">${escapeHtml(book.title)}</a>
      <p class="book-author">by ${escapeHtml(book.author)}</p>
    </div>
    ${book.status === '"'reading' ? "'`
      <form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
        <button type="submit">Mark finished</button>
      </form>
    ` : '"'<span class=\"status-pill\">Finished</span>'}
  </li>"'`;
}

function renderBookList(books, emptyMessage) {
  if (books.length === 0) {
    return `<p class="empty-state">${escapeHtml(emptyMessage)}</p>`;
  }

  return `<ul class="book-list">${books.map(renderBookItem).join('"'')}</ul>"'`;
}

app.get('"'/', async (_request, response, next) => {
  try {
    const books = await listBooks();
    const readingBooks = books.filter((book) => book.status === 'reading');
    const finishedBooks = books.filter((book) => book.status === 'finished');

    response.send(
      renderLayout({
        title: 'My Books',
        content: "'`
          <header>
            <h1>My books</h1>
            <p class="subtitle">Track what you are reading and what you have finished.</p>
          </header>

          <section class="panel">
            <h2>Add a book</h2>
            <form method="post" action="/books" class="book-form">
              <label>
                Title
                <input name="title" required maxlength="120" />
              </label>
              <label>
                Author
                <input name="author" required maxlength="120" />
              </label>
              <label>
                Notes
                <textarea name="notes" rows="4" maxlength="1000" placeholder="Optional notes"></textarea>
              </label>
              <button type="submit">Add book</button>
            </form>
          </section>

          <section class="panel">
            <h2>Currently reading</h2>
            ${renderBookList(readingBooks, '"'No books in progress yet.')}
          </section>

          <section class=\"panel\">
            <h2>Finished</h2>
            "'${renderBookList(finishedBooks, '"'No finished books yet.')}
          </section>
        "'`,
      }),
    );
  } catch (error) {
    next(error);
  }
});

app.post('"'/books', async (request, response, next) => {
  try {
    const title = String(request.body.title ?? '').trim();
    const author = String(request.body.author ?? '').trim();
    const notes = String(request.body.notes ?? '').trim();

    if ("'!title || !author) {
      response.status(400).send('"'Title and author are required.');
      return;
    }

    const createdBook = await addBook({ title, author, notes });
    response.redirect("'`/books/${encodeURIComponent(createdBook.id)}`);
  } catch (error) {
    next(error);
  }
});

app.post('"'/books/:id/finish', async (request, response, next) => {
  try {
    const updatedBook = await markBookFinished(request.params.id);

    if ("'!updatedBook) {
      response.status(404).send('"'Book not found.');
      return;
    }

    response.redirect('/');
  } catch (error) {
    next(error);
  }
});

app.get('/books/:id', async (request, response, next) => {
  try {
    const book = await getBookById(request.params.id);

    if ("'!book) {
      response.status(404).send('"'Book not found.');
      return;
    }

    const statusLabel = book.status === 'finished' ? 'Finished' : 'Currently reading';

    response.send(
      renderLayout({
        title: "'`${book.title} · My Books`,
        content: `
          <a class="back-link" href="/">← Back to all books</a>
          <article class="panel">
            <h1>${escapeHtml(book.title)}</h1>
            <p class="book-author detail-author">by ${escapeHtml(book.author)}</p>
            <p><strong>Status:</strong> ${statusLabel}</p>
            <h2>Notes</h2>
            <p class="notes">${book.notes ? escapeHtml(book.notes).replaceAll('"'\\n', '<br />') : 'No notes yet.'}</p>
            <h2>Share this book</h2>
            <p>Send this link to share this book:</p>
            <code class=\"share-link\">/books/"'${encodeURIComponent(book.id)}</code>
          </article>
        `,
      }),
    );
  } catch (error) {
    next(error);
  }
});

app.use((error, _request, response, _next) => {
  console.error(error);
  response.status(500).send('"'Something went wrong.');
});

app.listen(port, () => {
  console.log("'`Book tracker running on http://localhost:${port}`);
});
EOF
