  1	import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
  2	import path from 'node:path';
  3	import { randomUUID } from 'node:crypto';
  4	import { fileURLToPath } from 'node:url';
  5	
  6	const __filename = fileURLToPath(import.meta.url);
  7	const __dirname = path.dirname(__filename);
  8	const DATA_DIR = path.join(__dirname, '..', 'data');
  9	const BOOKS_FILE = path.join(DATA_DIR, 'books.json');
 10	
 11	async function ensureDataFile() {
 12	  await mkdir(DATA_DIR, { recursive: true });
 13	
 14	  try {
 15	    await readFile(BOOKS_FILE, 'utf8');
 16	  } catch (error) {
 17	    if (error.code === 'ENOENT') {
 18	      await writeFile(BOOKS_FILE, '[]\n', 'utf8');
 19	      return;
 20	    }
 21	
 22	    throw error;
 23	  }
 24	}
 25	
 26	async function loadBooks() {
 27	  await ensureDataFile();
 28	  const rawData = await readFile(BOOKS_FILE, 'utf8');
 29	
 30	  if (!rawData.trim()) {
 31	    return [];
 32	  }
 33	
 34	  try {
 35	    const parsed = JSON.parse(rawData);
 36	    return Array.isArray(parsed) ? parsed : [];
 37	  } catch {
 38	    return [];
 39	  }
 40	}
 41	
 42	async function saveBooks(books) {
 43	  await ensureDataFile();
 44	  const tempFile = `${BOOKS_FILE}.tmp`;
 45	  await writeFile(tempFile, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
 46	  await rename(tempFile, BOOKS_FILE);
 47	}
 48	
 49	export async function listBooks() {
 50	  const books = await loadBooks();
 51	
 52	  return books.sort((first, second) => {
 53	    if (first.status !== second.status) {
 54	      return first.status === 'reading' ? -1 : 1;
 55	    }
 56	
 57	    return new Date(second.createdAt).getTime() - new Date(first.createdAt).getTime();
 58	  });
 59	}
 60	
 61	export async function getBookById(id) {
 62	  const books = await loadBooks();
 63	  return books.find((book) => book.id === id) ?? null;
 64	}
 65	
 66	export async function addBook({ title, author, notes }) {
 67	  const books = await loadBooks();
 68	
 69	  const book = {
 70	    id: randomUUID(),
 71	    title,
 72	    author,
 73	    notes,
 74	    status: 'reading',
 75	    createdAt: new Date().toISOString(),
 76	    finishedAt: null,
 77	  };
 78	
 79	  books.push(book);
 80	  await saveBooks(books);
 81	
 82	  return book;
 83	}
 84	
 85	export async function markBookFinished(id) {
 86	  const books = await loadBooks();
 87	  const targetBook = books.find((book) => book.id === id);
 88	
 89	  if (!targetBook) {
 90	    return null;
 91	  }
 92	
 93	  if (targetBook.status !== 'finished') {
 94	    targetBook.status = 'finished';
 95	    targetBook.finishedAt = new Date().toISOString();
 96	    await saveBooks(books);
 97	  }
 98	
 99	  return targetBook;
100	}
